package com.jnapanam.sportszone.release1.controller;
import com.jnapanam.sportszone.release1.service.AdvancedLifecycleService;import java.time.*;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/release1") public class AdvancedLifecycleController{
 private final AdvancedLifecycleService s;public AdvancedLifecycleController(AdvancedLifecycleService s){this.s=s;}
 @PostMapping("/memberships/{id}/lifecycle")public Map<String,Object> membership(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.membership(uid(a),id,str(b,"action"),str(b,"details"));}
 @PostMapping("/memberships/{id}/entitlements")public Map<String,Object> entitlement(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.entitlement(uid(a),id,str(b,"entitlement"),Integer.parseInt(String.valueOf(b.getOrDefault("quantity",1))),str(b,"reference"));}
 @GetMapping("/memberships/{id}/history")public List<Map<String,Object>> history(@PathVariable UUID id){return s.membershipHistory(id);}
 @PostMapping("/training/batches/{id}/waitlist")public Map<String,Object> waitlist(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.waitlist(uid(a),id,str(b,"participantName"));}
 @PostMapping("/training/enrollments/{id}/lifecycle")public Map<String,Object> training(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.training(uid(a),id,str(b,"action"),str(b,"details"));}
 @PostMapping("/training/enrollments/{id}/progress")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','COACH')")public Map<String,Object> progress(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.progress(uid(a),id,str(b,"note"));}
 @PostMapping("/training/enrollments/{id}/certificate")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','COACH')")public Map<String,Object> certificate(@PathVariable UUID id){return s.certificate(id);}
 @PostMapping("/tournaments/{id}/officials")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','ORGANIZER')")public Map<String,Object> official(@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.official(id,str(b,"name"),str(b,"role"));}
 @PostMapping("/tournaments/{id}/results")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','ORGANIZER')")public Map<String,Object> result(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object>b){Object f=b.get("fixtureId");return s.result(uid(a),id,f==null?null:UUID.fromString(f.toString()),str(b,"result"),str(b,"reason"));}
 @PostMapping("/tournaments/results/{id}/approve")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')")public Map<String,Object> approve(Authentication a,@PathVariable UUID id){return s.approveResult(uid(a),id);}
 @PostMapping("/tournaments/{id}/financial-close")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')")public Map<String,Object> close(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.closeTournament(uid(a),id,Long.parseLong(String.valueOf(b.getOrDefault("incomePaise",0))),Long.parseLong(String.valueOf(b.getOrDefault("expensePaise",0))),str(b,"notes"));}
 @PostMapping("/account/data-request")public Map<String,Object> data(Authentication a,@RequestBody Map<String,Object>b){return s.dataRequest(uid(a),str(b,"requestType"),str(b,"notes"));}
 @PostMapping("/admin/account-merge")@PreAuthorize("hasRole('SUPER_ADMIN')")public Map<String,Object> merge(Authentication a,@RequestBody Map<String,Object>b){return s.mergeRequest(uid(a),UUID.fromString(str(b,"sourceUserId")),UUID.fromString(str(b,"targetUserId")),Boolean.parseBoolean(String.valueOf(b.getOrDefault("verifiedMobile",false))));}
 @PostMapping("/reminders")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public Map<String,Object> reminder(@RequestBody Map<String,Object>b){return s.schedule(UUID.fromString(str(b,"userId")),str(b,"category"),str(b,"referenceType"),b.get("referenceId")==null?null:UUID.fromString(str(b,"referenceId")),Instant.parse(str(b,"scheduledAt")));}
 @GetMapping("/admin/exception-summary")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')")public List<Map<String,Object>> reports(){return s.reports();}
 private static UUID uid(Authentication a){return UUID.fromString(a.getName());}private static String str(Map<String,Object>b,String k){Object v=b.get(k);return v==null?null:v.toString();}
}
